-- ════════════════════════════════════════════════════════════════
-- Leads batch 2 (2026-08): Gemini-scraped East End B2B / community orgs
--   Source: hh-scraped-contacts.csv.txt (85 rows; 44 already existed from the
--   prior ai-scrape-2026-08 batch, all is_business=true — SKIPPED, never touched).
--   Inserts the 41 genuinely-new orgs. Cold outreach: status='lead',
--   NO opt-in assumed (email/sms false). Idempotent: ON CONFLICT DO NOTHING.
--   Tags derived in-SQL from business_type + source_detail, scoped to this batch
--   so existing rows are never re-tagged. Reviewed before run.
-- ════════════════════════════════════════════════════════════════

ON CONFLICT (email) DO NOTHING;

-- Tags: category-slug + type (b2b-partner|community-outreach) + batch, derived from the just-inserted rows.
SELECT c.id, t.tg
FROM public.contacts c
CROSS JOIN LATERAL (VALUES
  (trim(both '-' from lower(regexp_replace(c.business_type, '[^a-zA-Z0-9]+', '-', 'g')))),
  (CASE WHEN c.source_detail LIKE '%b2b partnership%' THEN 'b2b-partner' ELSE 'community-outreach' END),
  ('ai-scrape-2026-08')
) AS t(tg)
WHERE c.source_detail LIKE 'gemini_scrape (hh-scraped batch 2026-08%'
ON CONFLICT (contact_id, tag) DO NOTHING;

